    #[tokio::test]
    async fn an_older_server_answers_method_not_found_to_discover() {
        // The specification's own backward-compatibility probe: no guessing needed.
        let mut f = ScriptedFetch::new(vec![ScriptedFetch::json(
            200,
            &serde_json::json!({
                "jsonrpc": "2.0", "id": 1,
                "error": { "code": proto::METHOD_NOT_FOUND, "message": "unknown method" }
            }),
        )]);
        let mut c = McpClient::new(&mut f, "https://old.example/mcp", me());
        match c.discover().await {
            Err(ClientError::Rpc { code, .. }) => assert_eq!(code, proto::METHOD_NOT_FOUND),
            other => panic!("expected an rpc error, got {other:?}"),
        }
    }

    struct FixedAnswer {
        answer: Value,
        asked: u32,
    }

    impl FixedAnswer {
        fn new(answer: Value) -> Self {
            Self { answer, asked: 0 }
        }
    }

    impl InputProvider for FixedAnswer {
        fn respond(&mut self, _: &Value) -> Option<Value> {
            self.asked += 1;
            Some(self.answer.clone())
        }
    }

    #[tokio::test]
    async fn input_required_is_answered_by_retrying_the_same_request() {
        let mut f = ScriptedFetch::new(vec![
            input_required(
                1,
                Some(serde_json::json!({ "a": { "method": "elicitation/create" } })),
                Some("blob"),
            ),
            // The retry travels under the NEXT id (SEP-2322), and the response
            // is correlated to it.
            ok(2, serde_json::json!({ "content": [] })),
        ]);
        let mut answers = FixedAnswer::new(serde_json::json!({ "a": { "action": "accept" } }));
        {
            let mut c = McpClient::new(&mut f, "https://h/mcp", me());
            c.call_tool("t", serde_json::json!({}), &mut answers)
                .await
                .expect("completes");
        }
        assert_eq!(f.seen.len(), 2, "one retry");
        let first = body_of(&f.seen[0]);
        let retry = body_of(&f.seen[1]);
        // THE SAME request: same method, same _meta, same arguments — under a
        // fresh JSON-RPC id, as SEP-2322 requires of a retry.
        assert_ne!(retry["id"], first["id"], "a retry uses a new JSON-RPC id");
        assert_eq!(retry["id"], serde_json::json!(2));
        assert_eq!(retry["method"], first["method"]);
        assert_eq!(retry["params"]["_meta"], first["params"]["_meta"]);
        assert_eq!(retry["params"]["name"], first["params"]["name"]);
        // Carrying the server's opaque state back, byte for byte.
        assert_eq!(retry["params"]["requestState"], serde_json::json!("blob"));
        assert_eq!(
            retry["params"]["inputResponses"]["a"]["action"],
            serde_json::json!("accept")
        );
    }

    #[tokio::test]
    async fn a_refused_version_is_retried_once_when_the_server_lists_ours() {
        // SEP-2575: the server names what it supports; when that includes a
        // version this client speaks, the request is re-sent once under it
        // (a fresh id). A second refusal is reported, not retried again.
        let refusal = || {
            ScriptedFetch::json(
                400,
                &serde_json::json!({
                    "jsonrpc": "2.0", "id": 1,
                    "error": { "code": proto::UNSUPPORTED_PROTOCOL_VERSION, "message": "nope",
                               "data": { "supported": [proto::PROTOCOL_VERSION], "requested": proto::PROTOCOL_VERSION } }
                }),
            )
        };
        let mut f = ScriptedFetch::new(vec![refusal(), ok(2, serde_json::json!({ "tools": [] }))]);
        {
            let mut c = McpClient::new(&mut f, "https://h/mcp", me());
            c.list_tools(None).await.expect("the retry completes");
        }
        assert_eq!(f.seen.len(), 2);
        assert_eq!(body_of(&f.seen[1])["id"], serde_json::json!(2));
        assert_eq!(
            body_of(&f.seen[1])["params"]["_meta"][proto::META_PROTOCOL_VERSION],
            serde_json::json!(proto::PROTOCOL_VERSION)
        );
        // The header follows the negotiated version, so header and _meta agree.
        assert_eq!(f.seen[1].header(proto::HEADER_PROTOCOL_VERSION), Some(proto::PROTOCOL_VERSION));

        // A refusal whose id is null (the server refused before reading the
        // id) is still this request's, when it is the only message.
        let mut f = ScriptedFetch::new(vec![
            ScriptedFetch::json(
                400,
                &serde_json::json!({
                    "jsonrpc": "2.0", "id": null,
                    "error": { "code": proto::UNSUPPORTED_PROTOCOL_VERSION, "message": "nope",
                               "data": { "supported": [proto::PROTOCOL_VERSION] } }
                }),
            ),
            ok(2, serde_json::json!({ "tools": [] })),
        ]);
        {
            let mut c = McpClient::new(&mut f, "https://h/mcp", me());
            c.list_tools(None).await.expect("negotiated after a null-id refusal");
        }
        assert_eq!(f.seen.len(), 2);

        // A server listing nothing we speak is a mismatch, reported once.
        let mut f = ScriptedFetch::new(vec![ScriptedFetch::json(
            400,
            &serde_json::json!({
                "jsonrpc": "2.0", "id": 1,
                "error": { "code": proto::UNSUPPORTED_PROTOCOL_VERSION, "message": "nope",
                           "data": { "supported": ["1999-01-01"], "requested": proto::PROTOCOL_VERSION } }
            }),
        )]);
        {
            let mut c = McpClient::new(&mut f, "https://h/mcp", me());
            match c.list_tools(None).await {
                Err(ClientError::Rpc { code, .. }) => assert_eq!(code, proto::UNSUPPORTED_PROTOCOL_VERSION),
                other => panic!("expected the version error, got {other:?}"),
            }
        }
        assert_eq!(f.seen.len(), 1, "no retry when nothing is mutually supported");
    }

    #[tokio::test]
    async fn load_shedding_is_re_driven_without_asking_anyone() {
        // requestState with no inputRequests: the server deferred the work and
        // wants only to be re-driven. NoInput must not abandon it.
        let mut f = ScriptedFetch::new(vec![
            input_required(1, None, Some("later")),
            ok(2, serde_json::json!({ "tools": [] })),
        ]);
        {
            let mut c = McpClient::new(&mut f, "https://h/mcp", me());
            c.list_tools(None)
                .await
                .expect("completes after being re-driven");
        }
        assert_eq!(f.seen.len(), 2);
        assert_eq!(
            body_of(&f.seen[1])["params"]["requestState"],
            serde_json::json!("later")
        );
    }

    #[tokio::test]
    async fn a_server_that_keeps_asking_is_a_loop_and_the_provider_is_not_over_asked() {
        // Without a bound the client loops with it. And the bound is checked BEFORE
        // another answer is obtained, so the provider is asked exactly the budget
        // and never once more to build a retry that is never sent.
        let asking = || {
            input_required(
                1,
                Some(serde_json::json!({ "a": { "method": "elicitation/create" } })),
                Some("again"),
            )
        };
        // Each round is answered to the id that round was sent under.
        let mut f = ScriptedFetch::new(vec![asking(), asking(), asking(), asking(), asking()]);
        f.correlate_ids = true;
        let mut answers = FixedAnswer::new(serde_json::json!({ "a": { "action": "accept" } }));
        {
            let mut c = McpClient::new(&mut f, "https://h/mcp", me());
            assert_eq!(
                c.call_tool("t", serde_json::json!({}), &mut answers).await,
                Err(ClientError::InputLoop)
            );
        }
        assert_eq!(
            answers.asked, MAX_MRTR_ROUNDS,
            "the provider is asked exactly the budget"
        );
        assert_eq!(
            f.seen.len() as u32,
            MAX_MRTR_ROUNDS + 1,
            "the original plus each retry"
        );
    }

    #[tokio::test]
    async fn a_client_that_cannot_answer_says_so_rather_than_reporting_a_loop() {
        // Sampling is deprecated and not offered, so declining is correct — and it
        // is NOT the same condition as a server that will not stop asking.
        let mut f = ScriptedFetch::new(vec![input_required(
            1,
            Some(serde_json::json!({ "a": { "method": "sampling/createMessage" } })),
            None,
        )]);
        let mut c = McpClient::new(&mut f, "https://h/mcp", me());
        assert_eq!(
            c.call_tool("t", serde_json::json!({}), &mut NoInput).await,
            Err(ClientError::InputUnavailable)
        );
    }

