    #[tokio::test]
    async fn an_uncorrelated_error_body_reports_the_status_not_the_error() {
        // A 500 whose JSON-RPC error answers a DIFFERENT request. Reporting its
        // message would attribute another request's failure to this one, so the
        // only honest answer is the status.
        let mut f = ScriptedFetch::new(vec![ScriptedFetch::json(
            500,
            &serde_json::json!({
                "jsonrpc": "2.0", "id": 42,
                "error": { "code": proto::INTERNAL_ERROR, "message": "somebody else's boom" }
            }),
        )]);
        let mut c = McpClient::new(&mut f, "https://h/mcp", me());
        assert_eq!(c.list_tools(None).await, Err(ClientError::Http(500)));
    }

