    #[tokio::test]
    async fn deprecated_capabilities_are_not_offered() {
        let mut f = ScriptedFetch::new(vec![ok(1, serde_json::json!({ "content": [] }))]);
        {
            let mut answers = FixedAnswer::new(serde_json::json!({}));
            let mut c = McpClient::new(&mut f, "https://h/mcp", me());
            c.call_tool("t", serde_json::json!({}), &mut answers)
                .await
                .expect("calls");
        }
        let caps = body_of(&f.seen[0])["params"]["_meta"][proto::META_CLIENT_CAPABILITIES].clone();
        // Roots, sampling and logging are deprecated in this revision.
        assert!(caps.get("roots").is_none());
        assert!(caps.get("sampling").is_none());
        assert!(caps.get("logging").is_none());
        // A provider that answers advertises elicitation, because MRTR uses it.
        assert!(caps.get("elicitation").is_some());
    }

    #[tokio::test]
    async fn capabilities_are_the_providers_so_no_input_advertises_nothing() {
        // Advertising elicitation on a NoInput call told the server it could
        // ask — it asked, and the call died with InputUnavailable. What the
        // provider cannot honour is not advertised.
        let mut f = ScriptedFetch::new(vec![ok(1, serde_json::json!({ "tools": [] }))]);
        {
            let mut c = McpClient::new(&mut f, "https://h/mcp", me());
            c.list_tools(None).await.expect("lists");
        }
        let caps = body_of(&f.seen[0])["params"]["_meta"][proto::META_CLIENT_CAPABILITIES].clone();
        assert_eq!(caps, serde_json::json!({}), "NoInput must advertise no capabilities");
    }

    #[tokio::test]
    async fn with_capabilities_is_an_explicit_override_of_the_derivation() {
        let mut f = ScriptedFetch::new(vec![ok(1, serde_json::json!({ "tools": [] }))]);
        {
            let mut c = McpClient::new(&mut f, "https://h/mcp", me())
                .with_capabilities(serde_json::json!({ "elicitation": { "form": {} } }));
            // NoInput drives the call, but the declaration wins.
            c.list_tools(None).await.expect("lists");
        }
        let caps = body_of(&f.seen[0])["params"]["_meta"][proto::META_CLIENT_CAPABILITIES].clone();
        assert!(caps.get("elicitation").is_some());
    }
